import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import * as api from "../utils/api";

function AdminDashboard() {
  const [accounts, setAccounts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const loadAccounts = async () => {
      try {
        const data = await api.fetchAccounts();

        console.log("Admin accounts:", data);

        setAccounts(data || []);
      } catch (error) {
        console.error("ADMIN ACCOUNTS ERROR:", error);

        setError(api.messageFromError(error));
      } finally {
        setLoading(false);
      }
    };

    loadAccounts();
  }, []);

  /* ================= LOADING ================= */

  if (loading) {
    return (
      <div className="dashboard-page">
        <div className="loading-card">

          <div className="loading-spinner"></div>

          <h2>Loading accounts...</h2>

          <p>
            Please wait while we fetch account information.
          </p>

        </div>
      </div>
    );
  }

  /* ================= ERROR ================= */

  if (error) {
    return (
      <div className="dashboard-page">

        <div className="error-card">

          <div className="status-icon">
            !
          </div>

          <h2>
            Unable to load accounts
          </h2>

          <p>
            {error}
          </p>

        </div>

      </div>
    );
  }

  /* ================= CALCULATIONS ================= */

  const totalBalance = accounts.reduce(
    (total, account) =>
      total + Number(account.balance || 0),
    0
  );

  const accountTypes = new Set(
    accounts.map(
      (account) => account.accountType
    )
  ).size;

  /* ================= MAIN DASHBOARD ================= */

  return (
    <div className="dashboard-page admin-dashboard">

      {/* ================= HEADER ================= */}

      <div className="dashboard-hero">

        <div>

          <span className="dashboard-label">
            ADMINISTRATION
          </span>

          <h1>
            Admin Dashboard ⚡
          </h1>

          <p>
            Manage customer accounts and banking operations.
          </p>

        </div>


        <Link
          className="admin-create-button"
          to="/accounts/new"
        >
          + Create Account
        </Link>

      </div>


      {/* ================= STATISTICS ================= */}

      <div className="admin-stats">

        <div className="stat-card">

          <span className="stat-icon">
            👥
          </span>

          <div>

            <p>
              Total Accounts
            </p>

            <h2>
              {accounts.length}
            </h2>

          </div>

        </div>


        <div className="stat-card">

          <span className="stat-icon">
            🏦
          </span>

          <div>

            <p>
              Account Types
            </p>

            <h2>
              {accountTypes}
            </h2>

          </div>

        </div>


        <div className="stat-card">

          <span className="stat-icon">
            ₹
          </span>

          <div>

            <p>
              Total Balance
            </p>

            <h2>
              ₹{totalBalance.toFixed(2)}
            </h2>

          </div>

        </div>

      </div>


      {/* ================= ACCOUNT SECTION ================= */}

      <div className="admin-section-header">

        <div>

          <span className="dashboard-label">
            ACCOUNT MANAGEMENT
          </span>

          <h2 className="section-heading">
            Customer Accounts
          </h2>

        </div>

        <span className="account-count">
          {accounts.length} Accounts
        </span>

      </div>


      {/* ================= EMPTY STATE ================= */}

      {accounts.length === 0 ? (

        <div className="empty-state">

          <div className="empty-icon">
            🏦
          </div>

          <h2>
            No Accounts Found
          </h2>

          <p>
            Create a customer account to get started.
          </p>

          <Link
            to="/accounts/new"
            className="primary"
          >
            + Create Account
          </Link>

        </div>

      ) : (

        /* ================= ACCOUNT LIST ================= */

        <div className="admin-account-grid">

          {accounts.map((account) => (

            <div
              className="admin-account-card"
              key={account.accountId}
            >

              {/* CARD HEADER */}

              <div className="admin-card-header">

                <div className="customer-avatar">
                  {account.accountHolderName
                    ? account.accountHolderName
                        .charAt(0)
                        .toUpperCase()
                    : "U"}
                </div>

                <div>

                  <h3>
                    {account.accountHolderName}
                  </h3>

                  <span>
                    {account.accountType}
                  </span>

                </div>

              </div>


              {/* BALANCE */}

              <div className="admin-balance">

                <span>
                  Current Balance
                </span>

                <strong>
                  ₹{Number(
                    account.balance || 0
                  ).toFixed(2)}
                </strong>

              </div>


              {/* DETAILS */}

              <div className="admin-account-details">

                <div>

                  <span>
                    Account Number
                  </span>

                  <strong>
                    {account.accountNumber}
                  </strong>

                </div>


                <div>

                  <span>
                    Owner
                  </span>

                  <strong>
                    {account.ownerUsername}
                  </strong>

                </div>

              </div>


              {/* BUTTON */}

              <Link
                className="account-details-button"
                to={`/accounts/${account.accountId}`}
              >
                View Account Details
                <span>→</span>
              </Link>

            </div>

          ))}

        </div>

      )}

    </div>
  );
}

export default AdminDashboard;
